let db=Store.get(),role=sessionStorage.getItem('tomi_role')||'admin',mechanicId='M1',activeTimer=null;
const pages={intake:'Príjem vozidla',inspections:'Obhliadky',tirehotel:'Pneuhotel',parking:'Vozidlá v areáli',dashboard:'Dashboard',bookings:'Rezervácie',calendar:'Kalendár dielne',history:'História práce',archive:'História zákaziek',jobs:'Servisné zákazky',quotes:'Cenové ponuky',parts:'Požiadavky na diely',customers:'Zákazníci a vozidlá',mechanic:'Mobil mechanika',economy:'Ekonomika',settings:'Nastavenia',expirations:'Končiace platnosti'};
function save(){Store.save(db)}function audit(text,job){db.activity.unshift({time:new Date().toISOString(),text,job});db.activity=db.activity.slice(0,400);save()}
function roleCheck(){if(role==='mechanic'&&!['mechanic','history','calendar'].includes(page())){location.hash='mechanic';return false}if(role==='technician'&&['economy','settings'].includes(page())){location.hash='dashboard';return false}return true}
function page(){return location.hash.slice(1).split('?')[0]||'dashboard'}function pageHeader(title,subtitle='',buttons=''){return `<div class="pagehead"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${buttons}</div></div>`}function field(label,name,value='',type='text',attrs=''){return `<div class="field"><label>${label}</label><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}function sel(label,name,opts,value=''){return `<div class="field"><label>${label}</label><select name="${name}">${opts.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(value)?'selected':''}>${esc(o[1])}</option>`).join('')}</select></div>`}function button(text,fn,cls=''){return `<button class="btn ${cls}" onclick="${fn}">${text}</button>`}function modal(html){document.getElementById('modalroot').innerHTML=`<div class="modalback" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="row between"><h2>${html.title||''}</h2><button class="close" onclick="closeModal()">×</button></div>${html.body||''}</div></div>`}function closeModal(){document.getElementById('modalroot').innerHTML=''}function formValues(form){return Object.fromEntries(new FormData(form))}function jobLabel(j){let v=vehicleOf(db,j);return `${v.make} · ${v.plate}`}function statusPill(s){let cl=/Ukončená|Pripravené|Vybavené|Schválená/.test(s)?'green':/Čaká|Objednané/.test(s)?'amber':/Nová|Urgent|Blokovaná/.test(s)?'red':'';return `<span class="pill ${cl}">${esc(s)}</span>`}function roleName(){return role==='admin'?'Administrátor':role==='technician'?'Technik':'Mechanik'}function render(){db=Store.get();if(!roleCheck())return;document.getElementById('roleBadge').textContent=roleName()+' · demo';document.getElementById('crumb').textContent=pages[page()]||'Dashboard';document.querySelectorAll('.navlink').forEach(a=>{if(a.dataset.page==='jobs'&&!a.dataset.tomiReset){a.addEventListener('click',()=>{window.tomiSelectedJob=null});a.dataset.tomiReset='1'}a.classList.toggle('active',a.dataset.page===page());a.style.display=(role==='mechanic'&&!['mechanic','calendar','history'].includes(a.dataset.page)||role==='technician'&&['economy','settings'].includes(a.dataset.page))?'none':''});document.getElementById('sidebar').classList.remove('open');let partNav=document.querySelector('.navlink[data-page=parts]');if(partNav){let n=db.jobs.reduce((a,j)=>a+(j.requests||[]).filter(r=>r.status==='Nová').length,0);partNav.querySelector('.request-alert')?.remove();if(n)partNav.insertAdjacentHTML('beforeend',`<span class="request-alert" style="color:#f43f5e;font-weight:900;margin-left:8px">❗ ${n}</span>`)}let fn=({dashboard,bookings,calendar,history,archive,intake,inspections,tirehotel,parking,jobs,quotes,parts,customers,mechanic,economy,settings,expirations})[page()]||dashboard;document.getElementById('app').innerHTML=fn()}

const vehicleStages=['Nadchádzajúce zákazky','Obhliadka','Čakajúce','Servis','Na odovzdanie','Odovzdané'];
function vehicleStage(j){if(j.vehicleStage)return j.vehicleStage;let x=j.status||'';return x==='Ukončená'?'Odovzdané':x==='Pripravená na odovzdanie'?'Na odovzdanie':x==='V oprave'||x==='Kontrola'?'Servis':x==='Obhliadka'?'Obhliadka':x==='Prijatá'||x.includes('Čaká')?'Čakajúce':'Nadchádzajúce zákazky'}
function inArea(j){return ['Obhliadka','Čakajúce','Servis','Na odovzdanie'].includes(vehicleStage(j))}
function localDay(d){return d?String(d).slice(0,10):''}
function calendarDays(date,end){if(!date)return null;let a=new Date(localDay(date)+'T12:00:00'),b=new Date(localDay(end||new Date().toISOString())+'T12:00:00');return Math.max(1,Math.round((b-a)/86400000)+1)}
function activeStay(j){return (j.stays||[]).findLast?.(x=>!x.out)||[...(j.stays||[])].reverse().find(x=>!x.out)||null}
function ensureStay(j){if(!Array.isArray(j.stays))j.stays=[];if(inArea(j)&&!activeStay(j))j.stays.push({in:j.arrivedAt||j.date||new Date().toISOString(),out:null});}
function changeVehicleStage(j,newStage){let prev=vehicleStage(j),now=new Date().toISOString();if(!Array.isArray(j.stays))j.stays=[];if(!j.vehicleStage&&inArea(j))ensureStay(j);if(!inArea(j)&&['Obhliadka','Čakajúce','Servis','Na odovzdanie'].includes(newStage))j.stays.push({in:now,out:null});if(inArea(j)&&['Nadchádzajúce zákazky','Odovzdané'].includes(newStage)){let stay=activeStay(j);if(stay)stay.out=now;}if(newStage==='Na odovzdanie'&&prev!=='Na odovzdanie')j.repairDoneAt=now;if(newStage==='Servis'&&prev==='Na odovzdanie')j.repairDoneAt=null;j.vehicleStage=newStage;if(newStage==='Odovzdané'){j.status='Ukončená';j.finishedAt=j.finishedAt||now}else if(newStage==='Na odovzdanie'){j.status='Pripravená na odovzdanie';j.finishedAt=null}else if(newStage==='Servis'){j.status='V oprave';j.finishedAt=null}else if(newStage==='Obhliadka'){j.status='Obhliadka';j.finishedAt=null}else if(newStage==='Čakajúce'){j.status='Čaká na diely';j.finishedAt=null}else{j.status='Prijatá';j.finishedAt=null}}
const workGroups=[['Olej a filtre',/olej|olejov|vzduchov.{0,8}filter|palivov.{0,8}filter|kab[ií]nov.{0,8}filter/i],['Brzdy',/brzd|kot[uú]č|platnič|strmeň/i],['Tlmiče',/tlmič|pružin|uloženie tlmič/i],['Ramená',/ramen|silentblok|čap riadenia/i],['Výfuk',/v[yý]fuk|katalyz[aá]tor|dpf|lambda sond/i],['Rozvody',/rozvod|vodn[aá] pump|nap[ií]nač/i],['Spojka',/spojk|zotrvačn/i],['Klimatizácia',/klimatiz|kompresor klimat/i],['Diagnostika',/diagnostik/i],['Prevodovka',/prevodovk/i],['Pneuservis',/pneumatik|prezut|vyv[aá]žen/i],['Alternátor a štartér',/altern[aá]tor|štart[eé]r/i]];
function suggestWork(j){let source=[j.description||'',...(j.parts||[]).map(p=>p.name),...(j.inspection||[]).map(x=>x.text||'')].join(' ');let groups=workGroups.filter(([name,re])=>re.test(source)).map(x=>x[0]);return groups.join(', ')||'Iné servisné práce'}
function workSummary(j){return j.workSummaryConfirmed?j.workSummary:(j.workSummary||suggestWork(j))}
function normSearch(v){return String(v||'').toLocaleLowerCase('sk').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\s-]/g,'')}
function jobSearchText(j){let v=vehicleOf(db,j),c=customerOf(db,j);return [j.id,j.date,c.name,v.plate,v.make,workSummary(j),String(jobTotals(j).labor+jobTotals(j).sell)].join(' ')}
function filterJobs(){let q=normSearch(document.getElementById('jobSearch')?.value),active=document.getElementById('showActive')?.checked,closed=document.getElementById('showClosed')?.checked;let n=0,sum=0;db.jobs.forEach((j,i)=>{let show=normSearch(jobSearchText(j)).includes(q)&&(isClosed(j)?closed:active);let el=document.getElementById('jobrow-'+i);if(el)el.style.display=show?'':'none';if(show){n++;sum+=jobTotals(j).labor+jobTotals(j).sell}});let el=document.getElementById('jobResults');if(el)el.textContent=n+' zákaziek · '+money(sum)+' celková hodnota'}
function saveWorkSummary(id){let j=db.jobs.find(x=>x.id===id);if(!j)return;j.workSummary=document.getElementById('workSummaryInput').value.trim()||suggestWork(j);j.workSummaryConfirmed=true;audit('Potvrdený stručný popis opravy',id);openJob(id,'overview')}
function suggestWorkInput(id){let j=db.jobs.find(x=>x.id===id);if(j)document.getElementById('workSummaryInput').value=suggestWork(j)}
function parking(){let list=db.jobs.filter(inArea);return pageHeader('Vozidlá v areáli','Fyzicky prítomné vozidlá · dni od prijatia a po oprave')+`<div class="grid four">${['Obhliadka','Čakajúce','Servis','Na odovzdanie'].map(st=>`<div class="card"><span class="muted">${st}</span><div class="metric">${list.filter(j=>vehicleStage(j)===st).length}</div></div>`).join('')}</div><div class="card" style="margin-top:20px"><div class="row between wrap"><h3>Parkovisko a servis · ${list.length} vozidiel</h3><input id="parkingSearch" placeholder="Zákazník, ŠPZ, auto..." oninput="filterParking()" style="max-width:300px"></div><div class="tablewrap"><table><thead><tr><th>Číslo zákazky</th><th>Vozidlo / ŠPZ</th><th>Zákazník</th><th>Stav</th><th>Od prijatia</th><th>Po oprave</th><th></th></tr></thead><tbody>${list.map(j=>{ensureStay(j);let st=activeStay(j);return `<tr class="parking-row" data-search="${esc(normSearch(jobSearchText(j)))}"><td><strong>${esc(j.id)}</strong></td><td>${esc(jobLabel(j))}</td><td>${esc(customerOf(db,j).name)}</td><td>${statusPill(vehicleStage(j))}</td><td>${calendarDays(st?.in)||'—'} dní</td><td>${j.repairDoneAt?calendarDays(j.repairDoneAt)+' dní':'—'}</td><td>${button('Detail',`openJob('${j.id}')`,'small outline')}</td></tr>`}).join('')}</tbody></table></div></div>`}
function filterParking(){let q=normSearch(document.getElementById('parkingSearch').value);document.querySelectorAll('.parking-row').forEach(r=>r.style.display=r.dataset.search.includes(q)?'':'none')}

function dashboard(){let open=db.jobs.filter(j=>!isClosed(j)),urgent=db.jobs.flatMap(j=>(j.requests||[]).filter(r=>r.status==='Nová').map(r=>({j,r})));let parked=db.jobs.filter(inArea);return pageHeader('Prehľad servisu','Stav zákaziek a fyzicky prítomných vozidiel',button('Končiace platnosti',"location.hash='expirations'",'outline')+button('Vozidlá v areáli',"location.hash='parking'",'outline')+button('+ Nová zákazka','newJob()'))+`<div class="grid four">${['Nadchádzajúce zákazky','Obhliadka','Čakajúce','Servis','Na odovzdanie'].map(st=>`<div class="card" style="cursor:pointer" onclick="location.hash='jobs';setTimeout(()=>{let e=document.getElementById('stageFilter');if(e){e.value='${st}';filterJobs()}},50)"><span class="muted">${st}</span><div class="metric">${db.jobs.filter(j=>vehicleStage(j)===st).length}</div></div>`).join('')}<div class="card" style="cursor:pointer;border-color:var(--blue)" onclick="location.hash='parking'"><span class="muted">VŠETKY AUTÁ V AREÁLI</span><div class="metric">${parked.length}</div><span class="pill">Zobraziť parkovisko</span></div></div><div class="grid two" style="margin-top:20px"><div class="card"><h3>Aktívne zákazky</h3>${open.map(j=>`<div class="jobcard"><div class="row between"><strong>${esc(jobLabel(j))}</strong>${statusPill(vehicleStage(j))}</div><div class="muted">${esc(j.id)} · ${esc(workSummary(j))}</div><div style="margin-top:10px">${button('Otvoriť',`openJob('${j.id}')`,'small outline')}</div></div>`).join('')||'<p class="muted">Žiadne aktívne zákazky.</p>'}</div><div class="card"><h3>Upozornenia a aktivita</h3>${urgent.map(x=>`<div class="notice danger">🔴 ${esc(x.r.name)} · ${esc(jobLabel(x.j))}</div>`).join('')}${db.activity.slice(0,8).map(a=>`<p style="font-size:13px;border-bottom:1px solid var(--line);padding-bottom:9px"><span class="muted">${fmt(a.time)}</span><br>${esc(a.text)}</p>`).join('')||'<p class="muted">Zatiaľ bez záznamov.</p>'}</div></div>`}
function bookings(){return pageHeader('Rezervácie','Požiadavky z webu a interné rezervácie',button('+ Rezervácia','newBooking()'))+`<div class="card tablewrap"><table><thead><tr><th>Termín</th><th>Zákazník</th><th>Vozidlo</th><th>Služba</th><th>Stav</th><th>Akcia</th></tr></thead><tbody>${db.bookings.map(b=>`<tr><td>${esc(b.date)}</td><td><strong>${esc(b.name)}</strong><br><span class="mini">${esc(b.phone)}</span></td><td>${esc(b.plate||'—')}</td><td>${esc(b.service)}</td><td>${statusPill(b.status)}</td><td>${button('Spracovať',`editBooking('${b.id}')`,'small outline')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Zatiaľ žiadne rezervácie. Vytvorte ich tu alebo na verejnom webe.</td></tr>'}</tbody></table></div>`}
function newBooking(){modal({title:'Nová rezervácia',body:`<form onsubmit="submitBooking(event)" class="grid two">${field('Meno *','name','','text','required')}${field('Telefón *','phone','','tel','required')}${field('E-mail','email','','email')}${field('ŠPZ','plate')}${field('Dátum','date',new Date().toISOString().slice(0,10),'date')}${field('Služba','service','Autoservis')}<div class="field" style="grid-column:1/-1"><label>Poznámka</label><textarea name="description"></textarea></div><button class="btn" type="submit">Uložiť rezerváciu</button></form>`})}function submitBooking(e){e.preventDefault();db.bookings.unshift({id:Store.id('R'),...formValues(e.target),status:'Nová',created:new Date().toISOString()});audit('Vytvorená rezervácia');closeModal();render()}function editBooking(id){let b=db.bookings.find(x=>x.id===id);modal({title:'Rezervácia · '+esc(b.name),body:`<p>${esc(b.description||'Bez poznámky')}</p><p><strong>${esc(b.phone)}</strong> · ${esc(b.email)}</p>${sel('Stav','status',['Nová','Potvrdená','Zrušená','Vybavená'].map(x=>[x,x]),b.status)}<div class="row wrap" style="margin-top:16px">${button('Uložiť stav',`bookingStatus('${id}')`)}${button('Vytvoriť zákazku',`bookingToJob('${id}')`,'outline')}</div>`})}function bookingStatus(id){db.bookings.find(b=>b.id===id).status=document.querySelector('[name=status]').value;audit('Aktualizovaný stav rezervácie');closeModal();render()}function bookingToJob(id){let b=db.bookings.find(x=>x.id===id);closeModal();newJob(b)}
function customers(){return pageHeader('Zákazníci a vozidlá','Kliknite na zákazníka alebo vozidlo pre úpravu',button('+ Zákazník','newCustomer()')+button('+ Vozidlo','newVehicle()','outline'))+`<div class="grid two"><div class="card tablewrap"><h3>Zákazníci</h3><input placeholder="Hľadať zákazníka" oninput="this.nextElementSibling.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(this.value.toLowerCase())?'':'none')"><table><thead><tr><th>Meno / Firma</th><th>Typ</th><th>Kontakt</th></tr></thead><tbody>${db.customers.map(c=>`<tr onclick="editCustomer('${c.id}')" style="cursor:pointer"><td><strong>${esc(c.name)}</strong></td><td>${esc(c.type)}</td><td>${esc(c.phone)}</td></tr>`).join('')}</tbody></table></div><div class="card tablewrap"><h3>Vozidlá</h3><input placeholder="Hľadať ŠPZ / vozidlo" oninput="this.nextElementSibling.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(this.value.toLowerCase())?'':'none')"><table><thead><tr><th>ŠPZ</th><th>Vozidlo</th><th>Majiteľ</th></tr></thead><tbody>${db.vehicles.map(v=>`<tr onclick="editVehicle('${v.id}')" style="cursor:pointer"><td><strong>${esc(v.plate)}</strong></td><td>${esc(v.make)}</td><td>${esc(db.customers.find(c=>c.id===v.customer)?.name||'—')}</td></tr>`).join('')}</tbody></table></div></div>`}
function customerForm(c={},id=''){let type=c.type||'FO';return `<form class="stack" onsubmit="saveCustomerRecord(event,'${id}')">${sel('Typ zákazníka','type',[['FO','Fyzická osoba'],['Firma','Firma']],type)}<div class="grid two">${field('Meno / názov firmy','name',c.name||'','text','required')}${field('Adresa','address',c.address||'')}${field('Telefón','phone',c.phone||'','tel')}${field('E-mail','email',c.email||'','email')}</div><div id="companyFields" class="grid two" style="display:${type==='Firma'?'grid':'none'}">${field('IČO','ico',c.ico||'')}${field('DIČ','dic',c.dic||'')}${field('IČ DPH','icdph',c.icdph||'')}${field('Zodpovedná osoba','contactPerson',c.contactPerson||'')}</div><button class="btn" type="submit">Uložiť zákazníka</button></form>`}
function editCustomer(id){let c=db.customers.find(x=>x.id===id);if(!c)return;modal({title:'Zákazník – '+esc(c.name),body:customerForm(c,id)});bindCustomerType()}
function newCustomer(){modal({title:'Nový zákazník',body:customerForm()});bindCustomerType()}
function bindCustomerType(){let e=document.querySelector('#modalroot [name=type]');if(e)e.addEventListener('change',()=>{document.getElementById('companyFields').style.display=e.value==='Firma'?'grid':'none'})}
function saveCustomerRecord(e,id){e.preventDefault();let values=formValues(e.target),c=id?db.customers.find(x=>x.id===id):null;if(!c){c={id:Store.id('C')};db.customers.push(c)}Object.assign(c,values);audit('Uložený zákazník '+c.name);closeModal();render()}
function vehicleForm(v={},id=''){return `<form class="grid two" onsubmit="saveVehicleRecord(event,'${id}')">${sel('Majiteľ','customer',db.customers.map(c=>[c.id,c.name]),v.customer||'')}${field('ŠPZ / EČV','plate',v.plate||'','text','required')}${field('Značka a model','make',v.make||'','text','required')}${field('VIN','vin',v.vin||'')}${field('Kilometre','km',v.km||0,'number','min="0"')}${field('Výkon (kW)','kw',v.kw||'','number','min="0" step="0.1"')}${field('Rok výroby','year',v.year||'','number','min="1900" max="2100"')}${field('Objem motora (cm³)','engineVolume',v.engineVolume||'','number','min="0"')}${validityFields(v)}<button class="btn" type="submit">Uložiť vozidlo</button></form>`}
function editVehicle(id){let v=db.vehicles.find(x=>x.id===id);if(!v)return;modal({title:'Vozidlo – '+esc(v.plate),body:vehicleForm(v,id)})}
function newVehicle(){modal({title:'Nové vozidlo',body:vehicleForm()})}
function saveVehicleRecord(e,id){e.preventDefault();let values=formValues(e.target),v=id?db.vehicles.find(x=>x.id===id):null;if(!v){v={id:Store.id('V')};db.vehicles.push(v)}Object.assign(v,values);audit('Uložené vozidlo '+v.plate);closeModal();render()}
function jobs(){return pageHeader('Servisné zákazky','Kliknutím na riadok otvoríte detail zákazky',button('+ Nová zákazka','newJob()'))+`<div class="card"><div class="field"><label>Hľadať podľa čísla, dátumu, zákazníka, ŠPZ, vozidla, opravy alebo ceny</label><input id="jobSearch" placeholder="Začnite písať..." oninput="filterJobs()"></div><div class="row wrap" style="gap:24px;margin:14px 0"><label><input type="checkbox" id="showActive" checked onchange="filterJobs()"> Aktívne</label><label><input type="checkbox" id="showClosed" onchange="filterJobs()"> Ukončené</label></div><p id="jobResults" class="muted">${db.jobs.length} zákaziek</p><div class="tablewrap"><table><thead><tr><th>Číslo zákazky</th><th>Dátum prijatia</th><th>Zákazník</th><th>ŠPZ</th><th>Vozidlo</th><th>Popis</th><th>Cena</th></tr></thead><tbody>${db.jobs.map((j,i)=>{let t=jobTotals(j),v=vehicleOf(db,j);return `<tr id="jobrow-${i}" onclick="openJob('${j.id}')" style="cursor:pointer;${isClosed(j)?'display:none;':''}"><td><strong>${esc(j.id)}</strong></td><td>${esc(j.date||'—')}</td><td>${esc(customerOf(db,j).name)}</td><td>${esc(v.plate)}</td><td>${esc(v.make)}</td><td>${esc(workSummary(j))}</td><td><strong>${money(t.labor+t.sell)}</strong>${!isClosed(j)?'<br><span class="mini">priebežná</span>':''}</td></tr>`}).join('')}</tbody></table></div></div>`}
function newJob(booking){modal({title:'Nová servisná zákazka',body:`<form id="newJobForm" onsubmit="submitJob(event)" class="stack"><div class="grid two"><div class="field"><label>Hľadať zákazníka</label><input type="search" id="newCustomerSearch" oninput="filterNewJobChoices()" placeholder="Meno alebo firma"></div><div class="field"><label>Hľadať vozidlo / ŠPZ</label><input type="search" id="newVehicleSearch" oninput="filterNewJobChoices()" placeholder="ŠPZ, značka, model"></div>${sel('Zákazník','customer',db.customers.map(c=>[c.id,c.name]))}${sel('Vozidlo','vehicle',db.vehicles.map(v=>[v.id,v.plate+' · '+v.make]))}${field('Kilometre pri prijatí','km','','number','min="0" required')}${sel('Mechanik','mechanic',[['','Nepridelený'],...db.mechanics.map(m=>[m.id,m.name])])}${field('Dátum','date',booking?.date||new Date().toISOString().slice(0,10),'date')}</div><div class="field"><label>Požiadavky zákazníka / interné poznámky</label><textarea name="description" rows="4">${esc(booking?.description||'')}</textarea></div><div class="row wrap"><button class="btn" type="submit">Vytvoriť zákazku</button>${button('+ Pridať zákazníka','newCustomerForJob()','outline')}${button('+ Pridať vozidlo','newVehicleForJob()','outline')}</div></form>`});let f=document.getElementById('newJobForm');f.elements.customer.addEventListener('change',()=>filterNewJobChoices());filterNewJobChoices()}
function filterNewJobChoices(){let f=document.getElementById('newJobForm');if(!f)return;let cs=document.getElementById('newCustomerSearch').value.toLocaleLowerCase('sk'),vs=document.getElementById('newVehicleSearch').value.toLocaleLowerCase('sk'),c=f.elements.customer,v=f.elements.vehicle,oldC=c.value,oldV=v.value;c.innerHTML=db.customers.filter(x=>x.name.toLocaleLowerCase('sk').includes(cs)).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');if([...c.options].some(o=>o.value===oldC))c.value=oldC;v.innerHTML=db.vehicles.filter(x=>x.customer===c.value&&[x.plate,x.make,x.vin].join(' ').toLocaleLowerCase('sk').includes(vs)).map(x=>`<option value="${esc(x.id)}">${esc(x.plate)} · ${esc(x.make)}</option>`).join('');if([...v.options].some(o=>o.value===oldV))v.value=oldV;let selected=db.vehicles.find(x=>x.id===v.value);if(selected&&!f.elements.km.value)f.elements.km.value=selected.km||''}
function newCustomerForJob(){let draft=jobDraft();newCustomer();let form=document.querySelector('#modalroot form');form.onsubmit=e=>{e.preventDefault();let c={id:Store.id('C'),...formValues(form)};db.customers.push(c);audit('Pridaný zákazník '+c.name);newJob();restoreJobDraft(draft);document.querySelector('#newJobForm [name=customer]').value=c.id;filterNewJobChoices()}}
function newVehicleForJob(){let draft=jobDraft();newVehicle();let form=document.querySelector('#modalroot form');if(draft.customer)form.elements.customer.value=draft.customer;form.onsubmit=e=>{e.preventDefault();let v={id:Store.id('V'),...formValues(form)};db.vehicles.push(v);audit('Pridané vozidlo '+v.plate);newJob();restoreJobDraft(draft);document.querySelector('#newJobForm [name=customer]').value=v.customer;filterNewJobChoices();document.querySelector('#newJobForm [name=vehicle]').value=v.id}}
function jobDraft(){let f=document.getElementById('newJobForm');return f?{...formValues(f),cs:document.getElementById('newCustomerSearch').value,vs:document.getElementById('newVehicleSearch').value}:{}}
function restoreJobDraft(d){let f=document.getElementById('newJobForm');if(!f)return;for(let [k,v] of Object.entries(d))if(f.elements[k])f.elements[k].value=v;document.getElementById('newCustomerSearch').value=d.cs||'';document.getElementById('newVehicleSearch').value=d.vs||'';filterNewJobChoices()}
function submitJob(e){e.preventDefault();let v=formValues(e.target),vehicle=db.vehicles.find(x=>x.id===v.vehicle);if(!vehicle||vehicle.customer!==v.customer)return toast('Vozidlo musí patriť vybranému zákazníkovi.');if(v.km===''||Number(v.km)<0)return toast('Vyplňte kilometre.');let id=Store.id('Z');vehicle.km=Number(v.km);db.jobs.unshift({id,...v,km:Number(v.km),labor:0,status:'Prijatá',parts:[],logs:[],requests:[],inspection:[],approved:false,finishedAt:null});audit('Založená zákazka '+id,id);closeModal();openJob(id,'overview')}

let detailTab='overview';
function openJob(id,tab='overview'){if(!db.jobs.some(j=>j.id===id))return;detailTab=tab;window.tomiSelectedJob=id;if(location.hash!=='#jobs'){location.hash='jobs'}render();document.getElementById('app').innerHTML=jobDetail(id)}
function jobDetail(id){let j=db.jobs.find(x=>x.id===id);if(!j)return jobs();let c=customerOf(db,j),v=vehicleOf(db,j),t=jobTotals(j);return pageHeader(esc(j.id),esc(v.make)+' · '+esc(v.plate),button('← Zoznam','window.tomiSelectedJob=null;render()','outline')+button('Prijímací protokol',`protocol('${id}','prijimaci')`,'outline')+button('Zákazkový list – technik',`printWorkSheet('${id}','technician')`,'outline')+button('Zákazkový list – zákazník',`printWorkSheet('${id}','customer')`,'outline')+button('Odovzdávací protokol',`protocol('${id}','odovzdavaci')`,'outline'))+`<div class="grid four" style="margin-bottom:20px"><div class="card"><span class="mini">Zákazník</span><h3>${esc(c.name)}</h3></div><div class="card"><span class="mini">Mechanik</span><h3>${esc(db.mechanics.find(m=>m.id===j.mechanic)?.name||'Nepridelený')}</h3></div><div class="card"><span class="mini">Stav</span><h3>${statusPill(j.status)}</h3></div><div class="card"><span class="mini">Vyúčtovanie</span><h3>${esc(j.invoiceNumber||j.billingType||'—')}</h3></div></div><div class="card" style="margin-bottom:16px"><div class="row wrap" style="gap:22px"><span><small>Odpracované hodiny</small><br><strong>${(j.logs||[]).reduce((a,x)=>a+Number(x.minutes||0)/60,0).toFixed(1)} h</strong></span><span><small>Celková cena bez DPH</small><br><strong>${money((j.workParts||[]).reduce((a,x)=>a+lineNet(x,'part'),0)+(j.workLabor||[]).reduce((a,x)=>a+lineNet(x,'labor'),0))}</strong></span><span><small>Nákup dielov</small><br><strong>${money((j.workParts||[]).reduce((a,x)=>a+Number(x.buy||0)*Number(x.qty||1),0))}</strong></span><span><small>Cena práce</small><br><strong>${money((j.workLabor||[]).reduce((a,x)=>a+lineNet(x,'labor'),0))}</strong></span><span><small>Rozdiel pred režijnými nákladmi</small><br><strong>${money((j.workParts||[]).reduce((a,x)=>a+lineNet(x,'part')-Number(x.buy||0)*Number(x.qty||1),0)+(j.workLabor||[]).reduce((a,x)=>a+lineNet(x,'labor'),0))}</strong></span></div></div><div class="tabs" style="margin-bottom:18px">${[['overview','Prehľad'],['inspection','Obhliadka'],['quote','CP a diely'],['workorder','Zákazka'],['requests','Potrebujem diel'],['timeline','História'],['close','Ukončiť zákazku']].map(([k,n])=>`<button class="tab ${detailTab===k?'active':''}" onclick="openJob('${id}','${k}')">${n}</button>`).join('')}</div><div class="card">${detailTab==='workorder'?workOrderView(j):detailTab==='close'?closeJobView(j):detailTab==='overview'?`<div class="grid two"><div class="stack"><h3>Interné poznámky / požiadavky</h3><textarea id="jobDescription" rows="4" style="width:100%">${esc(j.description||'')}</textarea>${button('Uložiť poznámky',`saveJobDescription('${id}')`,'small outline')}<div class="field"><label>Stručný popis opravy (technik potvrdí alebo prepíše)</label><input id="workSummaryInput" value="${esc(workSummary(j))}" placeholder="Napr. olej a filtre, brzdy"></div><div class="row wrap" style="margin-bottom:12px">${button('Potvrdiť popis',`saveWorkSummary('${id}')`,'small')}${button('Znovu navrhnúť',`suggestWorkInput('${id}')`,'small outline')}</div>${sel('Stav vozidla','vehicleStage',vehicleStages.map(x=>[x,x]),vehicleStage(j))}<p class="mini">${inArea(j)?'Vozidlo je v areáli. Dni od prijatia: '+(calendarDays((activeStay(j)||{in:j.date}).in)||1)+(j.repairDoneAt?' · Po oprave: '+calendarDays(j.repairDoneAt):''):'Vozidlo nie je v areáli.'}</p>${sel('Pridelený mechanik','mechanic', [['','Nepridelený'],...db.mechanics.map(m=>[m.id,m.name])],j.mechanic)}${sel('Stav zákazky','status',['Prijatá','Obhliadka','Čaká na schválenie CP','Čaká na diely','V oprave','Kontrola','Pripravená na odovzdanie','Ukončená'].map(x=>[x,x]),j.status)}${button('Uložiť zmeny',`updateJob('${id}')`)}</div><div><h3>Vyúčtovanie</h3><p>${esc(j.invoiceNumber?("Faktúra č. "+j.invoiceNumber):(j.billingType==="Hotovosť"?"Hotovosť":"Nevyúčtované"))}</p><h3>Finančný súhrn</h3><p>Práca: <strong>${money(t.labor)}</strong></p><p>Materiál predaj: <strong>${money(t.sell)}</strong></p><p>Materiál nákup: <strong>${money(t.buy)}</strong></p><p>Príspevok: <strong>${money(t.contribution)}</strong></p><p class="mini">Interná kalkulácia, bez plného daňového spracovania.</p></div></div>`:detailTab==='inspection'?`<h3>Protokol obhliadky</h3><p class="muted">Mechanik môže zapisovať aj diktovať zistenia pomocou mikrofónu klávesnice.</p>${(j.inspection||[]).map(x=>`<div class="jobcard"><strong>${esc(x.text)}</strong><span class="mini">${fmt(x.time)}</span></div>`).join('')}<div class="field"><label>Nové zistenie</label><textarea id="inspectionText" placeholder="Popis závady, odporúčanie, závažnosť..."></textarea></div><div style="margin-top:12px">${button('+ Pridať zistenie',`addInspection('${id}')`)}</div>`:detailTab==='quote'?quoteView(j):detailTab==='requests'?`<h3>Požiadavky na diely</h3>${(j.requests||[]).map((r,i)=>`<div class="jobcard"><strong>${esc(r.name)} · ${esc(r.qty)} ks</strong> ${statusPill(r.status)}${sel('Stav','requestStatus'+i,['Nová','Prevzatá','Objednané','Pripravené','Vybavené'].map(x=>[x,x]),r.status)}${button('Uložiť stav',`updateRequest('${id}',${i})`,'small')}</div>`).join('')||'<p>Bez požiadaviek.</p>'}`:`<h3>História zákazky</h3><div class="timeline">${[...db.activity.filter(a=>a.job===id),...(j.logs||[]).map(l=>({time:l.start,text:`${l.type}: ${l.minutes} min`}))].sort((a,b)=>b.time.localeCompare(a.time)).map(a=>`<div class="timelineitem">${esc(a.text)} · ${fmt(a.time)}</div>`).join('')||'Bez záznamov'}</div>`}</div>`}
function updateJob(id){let j=db.jobs.find(x=>x.id===id);j.mechanic=document.querySelector('[name=mechanic]').value;let status=document.querySelector('[name=status]').value,stage=document.querySelector('[name=vehicleStage]').value;changeVehicleStage(j,stage);if(status==='Ukončená'&&stage!=='Odovzdané'){j.status='Ukončená';j.finishedAt=j.finishedAt||new Date().toISOString();}else if(status==='Pripravená na odovzdanie'&&stage!=='Na odovzdanie')changeVehicleStage(j,'Na odovzdanie');else if(status!=='Ukončená'&&status!=='Pripravená na odovzdanie'&&status!==j.status)j.status=status;audit('Aktualizovaná zákazka: '+vehicleStage(j),id);openJob(id)}
function addInspection(id){let t=document.getElementById('inspectionText').value.trim();if(!t)return toast('Zadajte zistenie.');db.jobs.find(x=>x.id===id).inspection.push({text:t,time:new Date().toISOString()});audit('Pridané zistenie z obhliadky',id);openJob(id,'inspection')}function updateQuote(id){audit('Uložená cenová ponuka',id);openJob(id,'quote')}
function partForm(id,i=-1){let j=db.jobs.find(x=>x.id===id),p=i>=0?j.parts[i]:{name:'',qty:1,buy:0,sell:0,buyVat:customerOf(db,j).type==='FO'?'s DPH':'bez DPH',sellVat:'s DPH'};modal({title:i>=0?'Upraviť diel':'Pridať diel',body:`<form onsubmit="savePart(event,'${id}',${i})" class="grid two">${field('Názov dielu','name',p.name,'text','required')}${field('Množstvo','qty',p.qty,'number','min="1"')}${field('Nákup €/ks','buy',p.buy,'number','step="0.01" min="0"')}${field('Predaj €/ks','sell',p.sell,'number','step="0.01" min="0"')}${sel('Nákupná cena','buyVat',[['s DPH','s DPH'],['bez DPH','bez DPH']],p.buyVat)}${sel('Predajná cena','sellVat',[['s DPH','s DPH'],['bez DPH','bez DPH']],p.sellVat)}<button class="btn" type="submit">Uložiť diel</button></form>`})}function addPart(id){editQuoteLine(id,'part',-1)}function editPart(id,i){editQuoteLine(id,'part',i)}function savePart(e,id,i){e.preventDefault();let v=formValues(e.target),j=db.jobs.find(x=>x.id===id),p={...v,qty:Number(v.qty)||1,buy:Number(v.buy)||0,sell:Number(v.sell)||0};if(i>=0)j.parts[i]=p;else j.parts.push(p);audit('Pridaný alebo upravený diel '+p.name,id);closeModal();openJob(id,'quote')}function bulkPrice(id){modal({title:'Hromadná zmena predajných cien',body:`<p class="muted">Zmena sa aplikuje na aktuálne predajné ceny všetkých dielov zákazky. Nákupné ceny zostanú nezmenené.</p>${field('Zmena v % (napr. 15 alebo -10)','percent','15','number','step="0.1"')}<div style="margin-top:15px">${button('Použiť zmenu',`applyBulk('${id}')`)}</div>`})}function applyBulk(id){let v=Number(document.querySelector('[name=percent]').value);if(!Number.isFinite(v)||v<=-100)return toast('Neplatné percento.');db.jobs.find(x=>x.id===id).parts.forEach(p=>p.sell=Math.round(p.sell*(1+v/100)*100)/100);audit('Hromadná zmena predajných cien '+v+' %',id);closeModal();returnQuote(id)}function updateRequest(id,i){let j=db.jobs.find(x=>x.id===id);j.requests[i].status=document.querySelector('[name=requestStatus'+i+']').value;audit('Požiadavka na diel: '+j.requests[i].status,id);openJob(id,'requests')}
function quotes(){return pageHeader('Cenové ponuky','Kalkulácie sú prepojené so zákazkami',button('+ Vytvoriť novú cenovú ponuku','newQuote()'))+`<div class="grid three">${db.jobs.map(j=>{let t=jobTotals(j);return `<div class="card"><div class="row between">${statusPill(j.approved?'Schválená':'Rozpracovaná')}<span class="mini">${esc(j.id)}</span></div><h3>${esc(jobLabel(j))}</h3><p class="muted">${esc(customerOf(db,j).name)}</p><p>Práca: <strong>${money(t.labor)}</strong></p><p>Diely: <strong>${money(t.sell)}</strong></p><h3>Spolu: ${money(t.labor+t.sell)}</h3>${button('Otvoriť CP',`openQuoteOnly('${j.id}')`,'outline')}</div>`}).join('')}</div>`}
function parts(){let list=db.jobs.flatMap(j=>(j.requests||[]).map((r,i)=>({j,r,i})));return pageHeader('Požiadavky na diely','Nové požiadavky sa zobrazujú červenou farbou')+`<div class="card tablewrap"><table><thead><tr><th>Zákazka</th><th>Diel</th><th>Počet</th><th>Stav</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td>${esc(jobLabel(x.j))}</td><td><strong>${esc(x.r.name)}</strong></td><td>${esc(x.r.qty)}</td><td>${statusPill(x.r.status)}</td><td>${button('Otvoriť',`openJob('${x.j.id}','requests')`,'small outline')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Zatiaľ žiadne požiadavky.</td></tr>'}</tbody></table></div>`}
function calendar(){let date=window.calDate||new Date().toISOString().slice(0,10),mid=window.calMechanic||'all';let jobs=db.jobs.filter(j=>j.date===date&&(mid==='all'||j.mechanic===mid));return pageHeader('Kalendár dielne','Plánovanie zákaziek a kapacity mechanikov',button('+ Naplánovať zákazku','newJob()'))+`<div class="card"><div class="row wrap" style="margin-bottom:18px"><div class="field"><label>Dátum</label><input class="control" type="date" value="${date}" onchange="window.calDate=this.value;render()"></div>${sel('Mechanik','calMechanic',[['all','Všetci'],...db.mechanics.map(m=>[m.id,m.name])],mid)}</div><div class="tablewrap"><div class="calendar-grid"><div class="calcell calhead">Čas</div>${db.mechanics.map(m=>`<div class="calcell calhead">${esc(m.name)}</div>`).join('')}${Array.from({length:10},(_,i)=>{let h=i+8;return `<div class="calcell calhead">${String(h).padStart(2,'0')}:00</div>${db.mechanics.map(m=>`<div class="calcell">${h===8?jobs.filter(j=>j.mechanic===m.id).map(j=>`<div class="jobcard"><strong>${esc(jobLabel(j))}</strong>${esc(j.description||'')}<br><span class="mini">Odhad ${esc(j.planned)} h</span><br>${button('Detail',`openJob('${j.id}')`,'small outline')}</div>`).join(''):''}</div>`).join('')}`}).join('')}</div></div><p class="mini">V tejto verzii sa zákazky zobrazujú v dennom prehľade od 08:00. Presné plánovanie začiatkov, presúvanie myšou a detekcia kolízií sú ďalšou etapou.</p></div>`}
function history(){let mechanic=window.histMech||'all',period=window.histPeriod||'week',date=window.histDate||new Date().toISOString().slice(0,10);let now=new Date(),all=db.jobs.flatMap(j=>(j.logs||[]).map(l=>({...l,job:j}))).filter(l=>{let d=new Date(l.start),days=(now-d)/86400000;return (mechanic==='all'||l.mechanic===mechanic)&&(period==='all'||period==='day'&&l.start.slice(0,10)===new Date().toISOString().slice(0,10)||period==='week'&&days>=0&&days<7||period==='month'&&days>=0&&days<30||period==='custom'&&l.start.slice(0,10)===date)}).sort((a,b)=>b.start.localeCompare(a.start));let min=all.reduce((s,l)=>s+l.minutes,0);return pageHeader('História práce','Skutočne odpracovaný čas mechanikov podľa ŠTART / STOP',button('Export CSV','exportHistory()','outline'))+`<div class="card"><div class="row wrap" style="margin-bottom:20px">${sel('Mechanik','histMech',[['all','Všetci'],...db.mechanics.map(m=>[m.id,m.name])],mechanic)}${sel('Obdobie','histPeriod',[['day','Dnes'],['week','Posledných 7 dní'],['month','Posledných 30 dní'],['custom','Konkrétny dátum'],['all','Všetko']],period)}<div class="field"><label>Dátum</label><input class="control" type="date" value="${date}" onchange="window.histDate=this.value;render()"></div></div><div class="grid three" style="margin-bottom:20px"><div class="card"><span class="muted">Produktívny čas</span><div class="metric">${(min/60).toFixed(2)} h</div></div><div class="card"><span class="muted">Záznamy</span><div class="metric">${all.length}</div></div><div class="card"><span class="muted">Zákazky</span><div class="metric">${new Set(all.map(x=>x.job.id)).size}</div></div></div><div class="tablewrap"><table><thead><tr><th>Dátum</th><th>Mechanik</th><th>Zákazka</th><th>Činnosť</th><th>Od – do</th><th>Trvanie</th></tr></thead><tbody>${all.map(l=>`<tr><td>${dateOnly(l.start)}</td><td>${esc(db.mechanics.find(m=>m.id===l.mechanic)?.name||'—')}</td><td>${esc(jobLabel(l.job))}</td><td>${esc(l.type)}</td><td>${new Date(l.start).toLocaleTimeString('sk-SK',{hour:'2-digit',minute:'2-digit'})} – ${new Date(l.end).toLocaleTimeString('sk-SK',{hour:'2-digit',minute:'2-digit'})}</td><td>${l.minutes} min</td></tr>`).join('')||'<tr><td colspan="6" class="empty">Žiadne záznamy pre vybraný filter.</td></tr>'}</tbody></table></div></div>`}
function exportHistory(){let rows=[['Zákazka','Mechanik','Typ','Začiatok','Koniec','Minúty']];db.jobs.forEach(j=>(j.logs||[]).forEach(l=>rows.push([j.id,l.mechanic,l.type,l.start,l.end,l.minutes])));downloadFile('tomi-historia.csv','\ufeff'+csv(rows),'text/csv;charset=utf-8')}
function mechanic(){let jobs=db.jobs.filter(j=>j.mechanic===mechanicId&&!isClosed(j)),jid=window.mobileJob||jobs[0]?.id,j=db.jobs.find(x=>x.id===jid);let t=activeTimer;return pageHeader('Mobil mechanika','Zjednodušené pracovné rozhranie pre telefón / tablet')+`<div style="max-width:650px"><div class="card stack"><div class="row between"><strong>MOJE ZÁKAZKY</strong><span class="pill">${esc(db.mechanics.find(m=>m.id===mechanicId)?.name||'Mechanik')}</span></div>${sel('Pracovník','mobileMechanic',db.mechanics.map(m=>[m.id,m.name]),mechanicId)}${sel('Aktívna zákazka','mobileJob',jobs.map(x=>[x.id,jobLabel(x)]),jid)}${j?`<div class="notice"><strong>${esc(j.description||'Bez popisu')}</strong><br>${esc(j.id)} · plán ${esc(j.planned)} h</div><div class="grid three">${['Obhliadka / diagnostika','Práca','Skúšobná jazda'].map(x=>button(x,`startTimer('${j.id}','${x}')`,t?'outline':'')).join('')}</div>${t?`<div class="notice warn">Beží: ${esc(t.type)} · od ${fmt(t.start)}<div style="margin-top:12px">${button('■ STOP – uložiť čas','stopTimer()','red')}</div></div>`:''}<div class="field"><label>Zistenie / servisný záznam</label><textarea id="mechanicNote" placeholder="Napíšte alebo nadiktujte pomocou mikrofónu klávesnice..."></textarea></div>${button('+ Uložiť zistenie',`mobileInspection('${j.id}')`,'outline')}<h3 style="margin-bottom:0">Potrebujem diel</h3>${field('Názov dielu','requestName')}${field('Počet kusov','requestQty',1,'number','min="1"')}<div class="field"><label>Upresnenie</label><textarea id="requestNote" placeholder="Strana, označenie, urgencia..."></textarea></div>${button('🔴 Odoslať technikovi',`mobileRequest('${j.id}')`,'red')}<p class="mini">Diely a ceny spravuje technik. Mechanik ceny nevidí.</p>`:'<div class="empty">Žiadna pridelená aktívna zákazka.</div>'}</div></div>`}
function startTimer(id,type){if(activeTimer)return toast('Najskôr zastavte aktuálny časovač.');activeTimer={id,type,mechanic:mechanicId,start:new Date().toISOString()};toast('Časovač spustený. V demo verzii funguje len v otvorenej relácii.');render()}function stopTimer(){if(!activeTimer)return;let t=activeTimer,j=db.jobs.find(x=>x.id===t.id),end=new Date().toISOString(),minutes=Math.max(1,Math.round((new Date(end)-new Date(t.start))/60000));j.logs.push({mechanic:t.mechanic,type:t.type,start:t.start,end,minutes});activeTimer=null;audit('Mechanik ukončil '+t.type+' ('+minutes+' min)',j.id);render()}function mobileInspection(id){let text=document.getElementById('mechanicNote').value.trim();if(!text)return toast('Vyplňte zistenie.');db.jobs.find(x=>x.id===id).inspection.push({text,time:new Date().toISOString(),mechanic:mechanicId});audit('Mechanik pridal servisný záznam',id);render()}function mobileRequest(id){let name=document.querySelector('[name=requestName]').value.trim(),qty=Number(document.querySelector('[name=requestQty]').value)||1,note=document.getElementById('requestNote').value;if(!name)return toast('Vyplňte názov dielu.');db.jobs.find(x=>x.id===id).requests.push({name,qty,note,status:'Nová',mechanic:mechanicId,time:new Date().toISOString()});audit('🔴 Nová požiadavka na diel: '+name,id);render();toast('Požiadavka vytvorená. Technik ju uvidí červenou farbou.')}
function economy(){let month=window.econMonth||currentMonth(),segment=window.econSegment||'all',completed=db.jobs.filter(j=>isClosed(j)&&j.finishedAt.startsWith(month)&&(segment==='all'||customerOf(db,j).type===segment));let labor=0,sell=0,buy=0;completed.forEach(j=>{let t=jobTotals(j);labor+=t.labor;sell+=t.sell;buy+=t.buy});let fixed=db.fixed.reduce((s,x)=>s+Number(x.amount),0),margin=labor+sell-buy,profit=margin-fixed;return pageHeader('Ekonomika servisu','Do výsledku vstupujú iba ukončené zákazky',button('Export CSV','exportEconomy()','outline'))+`<div class="row wrap" style="margin-bottom:20px"><div class="field"><label>Mesiac</label><input class="control" type="month" value="${month}" onchange="window.econMonth=this.value;render()"></div>${sel('Segment','econSegment',[['all','Spolu'],['Firma','Firmy'],['FO','FO']],segment)}</div><div class="grid four"><div class="card"><span class="muted">Príjem za prácu</span><div class="metric">${money(labor)}</div></div><div class="card"><span class="muted">Príjem za materiál</span><div class="metric">${money(sell)}</div></div><div class="card"><span class="muted">Výdavky na materiál</span><div class="metric">${money(buy)}</div></div><div class="card"><span class="muted">Príspevok pred fixnými nákladmi</span><div class="metric">${money(margin)}</div></div></div><div class="grid two" style="margin-top:20px"><div class="card"><span class="muted">Výsledok po fixných nákladoch</span><div class="metric" style="color:${profit>=0?'var(--green)':'var(--red)'}">${money(profit)}</div><p>${profit<0?'Do bodu zvratu chýba '+money(-profit):'Fixné náklady sú pokryté'}</p><div class="progress"><div style="width:${fixed?Math.min(100,Math.max(0,margin/fixed*100)):100}%"></div></div><p class="mini">Fixné náklady ${money(fixed)} / mesiac. Pri filtrovaní jedného segmentu sa porovnáva s celými fixnými nákladmi.</p></div><div class="card"><h3>Fixné mesačné náklady · len admin</h3>${db.fixed.map(f=>`<div class="row between" style="margin:12px 0"><span>${esc(f.name)}</span><strong>${money(f.amount)}</strong></div>`).join('')}<hr style="border:0;border-top:1px solid var(--line)"><div class="row between"><strong>Spolu</strong><strong>${money(fixed)}</strong></div>${button('Spravovať náklady',"location.hash='settings'",'outline small')}</div></div><div class="card" style="margin-top:20px"><h3>Ukončené zákazky v období</h3><div class="tablewrap"><table><thead><tr><th>Zákazka</th><th>Zákazník</th><th>Dátum ukončenia</th><th>Práca</th><th>Materiál</th><th>Nákup</th><th>Príspevok</th></tr></thead><tbody>${completed.map(j=>{let t=jobTotals(j);return `<tr><td>${esc(j.id)}</td><td>${esc(customerOf(db,j).name)}</td><td>${dateOnly(j.finishedAt)}</td><td>${money(t.labor)}</td><td>${money(t.sell)}</td><td>${money(t.buy)}</td><td><strong>${money(t.contribution)}</strong></td></tr>`}).join('')||'<tr><td colspan="7" class="empty">Žiadne ukončené zákazky v období.</td></tr>'}</tbody></table></div><p class="notice warn">Toto je manažérska kalkulácia, nie účtovná závierka. Daňové režimy, odpočítateľná DPH, historické sadzby a ďalšie variabilné náklady vyžadujú dokončenie pred ostrou prevádzkou.</p></div>`}
function exportEconomy(){let rows=[['Zákazka','Zákazník','Ukončená','Práca','Materiál predaj','Materiál nákup','Príspevok']];db.jobs.filter(isClosed).forEach(j=>{let t=jobTotals(j);rows.push([j.id,customerOf(db,j).name,j.finishedAt,t.labor,t.sell,t.buy,t.contribution])});downloadFile('tomi-ekonomika.csv','\ufeff'+csv(rows),'text/csv;charset=utf-8')}
function settings(){return pageHeader('Nastavenia','Správa nákladov, dát a prístupových režimov')+`<div class="grid two"><div class="card"><h3>Fixné mesačné náklady</h3>${db.fixed.map(f=>`<div class="row" style="margin:10px 0"><span style="flex:1">${esc(f.name)}</span><strong>${money(f.amount)}</strong>${button('×',`removeFixed('${f.id}')`,'small outline')}</div>`).join('')}${button('+ Pridať položku','addFixed()','outline')}</div><div class="card"><h3>Testovacie roly</h3><p class="muted">Prepnutie roly slúži len na demonštráciu rozhrania. Nejde o bezpečné prihlasovanie.</p>${sel('Rola','role',[['admin','Administrátor'],['technician','Technik'],['mechanic','Mechanik']],role)}<h3>Záloha demo údajov</h3><div class="row wrap">${button('Export JSON','backup()','outline')}${button('Import JSON','importBackup()','outline')}${button('Reset demo','resetDemo()','red')}</div><p class="mini">Údaje sa ukladajú v localStorage tohto prehliadača, nie do centrálnej databázy.</p></div></div>`}
function removeFixed(id){if(!confirm('Odstrániť položku?'))return;db.fixed=db.fixed.filter(x=>x.id!==id);audit('Odstránený fixný náklad');render()}function addFixed(){modal({title:'Nový mesačný náklad',body:`<form onsubmit="saveFixed(event)" class="stack">${field('Názov','name','','text','required')}${field('Mesačná suma (€)','amount','0','number','min="0" step="0.01"')}<button class="btn">Uložiť</button></form>`})}function saveFixed(e){e.preventDefault();let x=formValues(e.target);db.fixed.push({id:Store.id('F'),name:x.name,amount:Number(x.amount)||0});audit('Pridaný fixný náklad');closeModal();render()}function backup(){downloadFile('autoservis-tomi-demo.json',JSON.stringify(db,null,2))}function importBackup(){modal({title:'Import demo údajov',body:`<p class="notice warn">Import prepíše všetky lokálne demo údaje.</p><input type="file" id="importFile" accept="application/json,.json"><div style="margin-top:16px">${button('Importovať','doImport()')}</div>`})}async function doImport(){let f=document.getElementById('importFile').files[0];if(!f)return;try{let x=JSON.parse(await f.text());if(!Array.isArray(x.jobs)||!Array.isArray(x.customers)||!Array.isArray(x.fixed))throw Error('Neplatný formát');db=x;save();closeModal();render();toast('Import dokončený')}catch(e){toast('Import zlyhal: '+e.message)}}function resetDemo(){if(confirm('Vymazať lokálne údaje a obnoviť ukážku?')){db=Store.seed();save();render()}}
function protocol(id,type){let j=db.jobs.find(x=>x.id===id),c=customerOf(db,j),v=vehicleOf(db,j),title=type==='prijimaci'?'Prijímací protokol':'Odovzdávací protokol',works=type==='prijimaci'?`<p><strong>Požiadavky zákazníka:</strong> ${esc(j.description)}</p>`:`<p><strong>Vykonané práce:</strong> ${esc(j.description)}</p><p><strong>Použité diely:</strong> ${(j.parts||[]).map(p=>esc(p.name)+' ('+p.qty+' ks)').join(', ')||'—'}</p>`;modal({title,body:`<div id="protocolContent" style="border:1px solid var(--line);padding:20px;border-radius:10px"><h2>${title.toUpperCase()}</h2><p><strong>AUTOSERVIS TOMI</strong> · ${esc(j.id)}</p><p><strong>Zákazník:</strong> ${esc(c.name)} · ${esc(c.email)}</p><p><strong>Vozidlo:</strong> ${esc(v.make)} · ${esc(v.plate)} · VIN ${esc(v.vin||'—')}</p><p><strong>Kilometre:</strong> ${esc(v.km||'—')}</p><p><strong>Dátum:</strong> ${new Date().toLocaleDateString('sk-SK')}</p>${works}<p><strong>Stav vozidla / poznámky:</strong> __________________________________</p><p><strong>Odovzdané kľúče:</strong> __________</p><p style="margin-top:50px">Podpis zákazníka: _____________________ &nbsp; Podpis technika: _____________________</p></div><div class="row wrap" style="margin-top:18px">${button('✉ E-mail',`emailProtocol('${id}','${type}')`)}${button('▤ PDF / Tlačiť',`printProtocol()`,'outline')}</div><p class="mini">PDF sa vytvorí cez tlačový dialóg prehliadača (Uložiť ako PDF). E-mail zatiaľ otvorí návrh správy; automatické odoslanie PDF bude potrebovať backend.</p>`})}
function emailProtocol(id,type){let j=db.jobs.find(x=>x.id===id),c=customerOf(db,j),label=type==='prijimaci'?'prijímací':'odovzdávací';let subject=`AUTOSERVIS TOMI – ${label} protokol ${j.id}`,body=`Dobrý deň,\n\nposielame Vám ${label} protokol k zákazke ${j.id}.\n\nS pozdravom\nAUTOSERVIS TOMI\n\nPoznámka: PDF protokol je potrebné priložiť ručne.`;location.href=`mailto:${encodeURIComponent(c.email||'')}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
function printProtocol(){let html=document.getElementById('protocolContent').innerHTML,w=window.open('','_blank');if(!w)return toast('Povoľte otváranie okien pre tlač.');w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Protokol</title><style>body{font:14px Arial;padding:40px;color:#12223a}h2{margin-bottom:35px}p{line-height:1.8}</style></head><body>${html}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}

// Pracovný tok: príjem -> obhliadka -> CP -> zákazka -> odovzdanie.
function intake(){return pageHeader('Príjem vozidla','Prvý krok servisného procesu: zákazník, vozidlo, požiadavky a prijímací protokol',button('+ Prijať vozidlo','newJob()'))+`<div class="grid two"><div class="card"><h3>Prichádzajúce rezervácie</h3>${db.bookings.filter(b=>b.status!=='Zrušená').map(b=>`<div class="jobcard"><strong>${esc(b.name)}</strong><p class="muted">${esc(b.plate||'Bez ŠPZ')} · ${esc(b.date)}</p>${button('Prijať vozidlo',`bookingToJob('${b.id}')`,'small outline')}</div>`).join('')||'<p class="muted">Žiadne čakajúce rezervácie.</p>'}</div><div class="card"><h3>Prijaté vozidlá</h3>${db.jobs.filter(j=>!isClosed(j)).map(j=>`<div class="jobcard"><strong>${esc(jobLabel(j))}</strong><p class="muted">${esc(j.id)} · ${esc(j.description)}</p><div class="row wrap">${button('Prijímací protokol',`protocol('${j.id}','prijimaci')`,'small outline')}${button('Obhliadka',`location.hash='inspections'`,'small')}</div></div>`).join('')||'<p class="muted">Zatiaľ žiadne prijaté vozidlá.</p>'}</div></div>`}
function inspections(){return pageHeader('Obhliadky','Prehľad obhliadok podľa zákaziek')+`<div class="card"><div class="field"><label>Vyhľadávanie</label><input id="inspectionSearch" oninput="document.querySelectorAll('#inspectionRows tr').forEach(r=>r.style.display=r.textContent.toLocaleLowerCase('sk').includes(this.value.toLocaleLowerCase('sk'))?'':'none')" placeholder="Číslo, zákazník, ŠPZ, vozidlo, mechanik"></div><div class="tablewrap"><table><thead><tr><th>Číslo zákazky</th><th>Dátum</th><th>Zákazník</th><th>ŠPZ</th><th>Vozidlo</th><th>Mechanik</th><th>Stav</th></tr></thead><tbody id="inspectionRows">${db.jobs.map(j=>{let v=vehicleOf(db,j);return `<tr onclick="openInspection('${j.id}')" style="cursor:pointer"><td>${esc(j.id)}</td><td>${esc(j.date||'')}</td><td>${esc(customerOf(db,j).name)}</td><td>${esc(v.plate)}</td><td>${esc(v.make)}</td><td>${esc(db.mechanics.find(m=>m.id===j.mechanic)?.name||'Nepridelený')}</td><td>${(j.inspection||[]).length} zistení</td></tr>`}).join('')}</tbody></table></div></div>`}

function openInspection(id){let j=db.jobs.find(x=>x.id===id);if(!j)return;modal({title:'Obhliadka · '+esc(jobLabel(j)),body:`<p class="muted">${esc(j.id)} · Zistenia mechanika; bez cenových údajov.</p><div class="notice">Hlasový vstup: na mobile je možné použiť diktovanie na klávesnici. Automatický prepis a rozdelenie závad zatiaľ nie sú zapojené.</div><form onsubmit="saveInspection(event,'${id}')" class="stack"><div class="field"><label>Čo bolo zistené</label><textarea name="finding" required placeholder="Napr. predné brzdové kotúče opotrebované, pravý tlmič tečie..." rows="5"></textarea></div>${sel('Závažnosť','severity',[['Nízka','Nízka'],['Stredná','Stredná'],['Vysoká','Vysoká']])}<button class="btn" type="submit">Uložiť zistenie</button></form><h3>Protokol obhliadky</h3>${(j.inspection||[]).map(x=>`<div class="jobcard"><strong>${esc(x.severity)}</strong><p>${esc(x.finding)}</p><span class="mini">${esc(x.time)}</span></div>`).join('')||'<p class="muted">Zatiaľ bez zistení.</p>'}<div style="margin-top:12px">${button('Prejsť na cenové ponuky',"closeModal();location.hash='quotes'",'outline')}</div>`})}
function saveInspection(e,id){e.preventDefault();let j=db.jobs.find(x=>x.id===id);j.inspection=j.inspection||[];j.inspection.push({...formValues(e.target),time:new Date().toLocaleString('sk-SK')});audit('Pridané zistenie z obhliadky',id);openInspection(id)}
function tirehotel(){db.tirehotel=db.tirehotel||[];return pageHeader('Pneuhotel','Evidencia uskladnených pneumatík a kolies',button('+ Prijať pneumatiky','newTireStorage()'))+`<div class="card tablewrap"><table><thead><tr><th>Zákazník</th><th>Vozidlo / ŠPZ</th><th>Sada</th><th>Rozmer</th><th>Pozícia</th><th>Prijaté</th><th>Stav</th></tr></thead><tbody>${db.tirehotel.map(x=>`<tr><td>${esc(x.customer)}</td><td>${esc(x.plate)}</td><td>${esc(x.kind)}</td><td>${esc(x.size)}</td><td>${esc(x.position)}</td><td>${esc(x.date)}</td><td>${statusPill(x.status)}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">Zatiaľ žiadne uskladnené pneumatiky.</td></tr>'}</tbody></table></div>`}
function newTireStorage(){modal({title:'Príjem do pneuhotela',body:`<form class="grid two" onsubmit="saveTireStorage(event)">${field('Zákazník','customer','','text','required')}${field('ŠPZ','plate','','text','required')}${sel('Typ sady','kind',[['Letné','Letné'],['Zimné','Zimné'],['Celoročné','Celoročné']])}${field('Rozmer pneumatík','size','205/55 R16')}${field('Pozícia v sklade','position')}${field('Počet kusov','count','4','number','min="1" max="20"')}${field('Hĺbka dezénu / poznámka','note')}<button class="btn" type="submit">Uložiť sadu</button></form>`})}
function saveTireStorage(e){e.preventDefault();db.tirehotel=db.tirehotel||[];db.tirehotel.unshift({...formValues(e.target),id:Store.id('PH'),date:new Date().toLocaleDateString('sk-SK'),status:'Uskladnené'});audit('Prijatá sada pneumatík do pneuhotela');closeModal();render()}


// Importovaný archív starých zákaziek: uchováva celý pôvodný záznam, bez straty neznámych polí.
function archivedJobs(){try{return JSON.parse(localStorage.getItem('tomi_legacy_archive_v1')||'[]')}catch(e){return []}}
function archive(){let records=archivedJobs();return pageHeader('História zákaziek','Archív pôvodných zákaziek Provax · kompletné detaily a vyhľadávanie')+`<div class="card"><p class="muted">Importujte export vo formáte JSON alebo CSV. Archív sa v tejto demo verzii ukladá iba do prehliadača, nie na server. Pri importe sa zachovajú všetky dostupné pôvodné polia.</p><div class="row wrap"><input type="file" id="archiveFile" accept=".json,.csv,application/json,text/csv"><button class="btn" onclick="importArchive()">Importovať súbor</button><button class="btn outline" onclick="exportArchive()">Zálohovať JSON</button></div><p class="muted" id="archiveMessage">${records.length} importovaných zákaziek</p><div class="grid two">${field('Hľadať','archiveSearch','','text','id="archiveSearch" placeholder="Číslo, firma, zákazník, ŠPZ, auto, oprava..." oninput="filterArchive()"')}<div class="field"><label>Filtrovať práce</label><select id="archiveWork" onchange="filterArchive()"><option value="">Všetky práce</option>${['Olej a filtre','Brzdy','Tlmiče','Ramená','Výfuk','Rozvody','Spojka','Diagnostika','Klimatizácia'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="tablewrap"><table><thead><tr><th>Číslo</th><th>Dátum</th><th>Zákazník / firma</th><th>Vozidlo / ŠPZ</th><th>Stručne práce</th><th>Cena</th><th></th></tr></thead><tbody id="archiveRows">${records.map((r,i)=>archiveRow(r,i)).join('')||'<tr><td colspan="7">Zatiaľ žiadne importované zákazky.</td></tr>'}</tbody></table></div></div>`}
function archiveValue(r,keys){for(let k of keys){let v=r[k];if(v!==undefined&&v!==null&&v!=='')return typeof v==='object'?JSON.stringify(v):String(v)}return ''}
function archiveWorkSummary(r){let existing=archiveValue(r,['strucnyPopis','workSummary','oprava','prace','práce','description','popis']);if(existing)return existing;let raw=JSON.stringify(r).toLowerCase();let rules=[['olej','Olej a filtre'],['brzd','Brzdy'],['tlmič','Tlmiče'],['ramen','Ramená'],['výfuk','Výfuk'],['rozvod','Rozvody'],['spojk','Spojka'],['diagnost','Diagnostika'],['klimatiz','Klimatizácia']];return rules.filter(x=>raw.includes(x[0])).map(x=>x[1]).join(', ')||'—'}
function archiveRow(r,i){let num=archiveValue(r,['cislo','číslo','number','jobNumber','id','zakazka','zákazka']);let client=archiveValue(r,['zakaznik','zákazník','customer','client','firma','name']);let car=archiveValue(r,['vozidlo','vehicle','auto','model','car']);let plate=archiveValue(r,['spz','ŠPZ','ecv','EČV','plate']);let price=archiveValue(r,['cena','price','total','suma','celkom']);let date=archiveValue(r,['datum','dátum','date','createdAt']);let desc=r._tomiSummary||archiveWorkSummary(r);return `<tr class="archiveRow" data-index="${i}" data-search="${esc(JSON.stringify(r).toLowerCase()+' '+desc.toLowerCase())}"><td>${esc(num||'—')}</td><td>${esc(date||'—')}</td><td>${esc(client||'—')}</td><td>${esc((car+' '+plate).trim()||'—')}</td><td>${esc(desc)}</td><td>${esc(price||'—')}</td><td><button class="btn outline small" onclick="openArchive(${i})">Detail</button></td></tr>`}
function filterArchive(){let q=(document.getElementById('archiveSearch')?.value||'').toLowerCase(),w=(document.getElementById('archiveWork')?.value||'').toLowerCase();document.querySelectorAll('.archiveRow').forEach(tr=>{let r=archivedJobs()[Number(tr.dataset.index)],summary=(r._tomiSummary||archiveWorkSummary(r)).toLowerCase();tr.style.display=tr.dataset.search.includes(q)&&summary.includes(w)?'':'none'})}
function openArchive(i){let r=archivedJobs()[i];if(!r)return;let summary=r._tomiSummary||archiveWorkSummary(r);modal({title:'Historická zákazka',body:`<p class="muted">Úplný importovaný záznam</p><div class="field"><label>Stručný popis (technik môže potvrdiť/upraviť)</label><input id="archiveSummary" value="${esc(summary)}"></div><button class="btn" onclick="saveArchiveSummary(${i})">Uložiť popis</button><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:55vh;overflow:auto">${esc(JSON.stringify(r,null,2))}</pre>`})}
function saveArchiveSummary(i){let a=archivedJobs();if(!a[i])return;a[i]._tomiSummary=document.getElementById('archiveSummary').value;localStorage.setItem('tomi_legacy_archive_v1',JSON.stringify(a));closeModal();render()}
function parseArchiveCSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===','||c===';'||c==='\t'){if(quoted)cell+=c;else{row.push(cell);cell=''}}else if(c==='\n'&&!quoted){row.push(cell);rows.push(row);row=[];cell=''}else if(c!=='\r'||quoted)cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}if(rows.length<2)return [];let h=rows.shift();return rows.filter(r=>r.some(Boolean)).map(r=>Object.fromEntries(h.map((k,i)=>[k.trim(),r[i]||''])))}
async function importArchive(){let f=document.getElementById('archiveFile')?.files?.[0];if(!f){alert('Vyberte JSON alebo CSV súbor.');return}try{let t=await f.text(),parsed=f.name.toLowerCase().endsWith('.json')?JSON.parse(t):parseArchiveCSV(t);let incoming=Array.isArray(parsed)?parsed:(parsed.jobs||parsed.zakazky||parsed.zákazky||parsed.data||[]);if(!Array.isArray(incoming)||!incoming.length)throw Error('Nenašli sa žiadne zákazky.');let old=archivedJobs(),seen=new Set(old.map(x=>JSON.stringify(x)));let added=0;for(let x of incoming){if(!x||typeof x!=='object')continue;let key=JSON.stringify(x);if(!seen.has(key)){old.push(x);seen.add(key);added++}}localStorage.setItem('tomi_legacy_archive_v1',JSON.stringify(old));alert(`Import dokončený. Nových záznamov: ${added}. Spolu: ${old.length}.`);render()}catch(e){alert('Import sa nepodaril: '+e.message)}}
function exportArchive(){let blob=new Blob([JSON.stringify(archivedJobs(),null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='tomi-historia-zakaziek.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}


// Platnosti dokladov vozidiel – lokálna demo evidencia; žiadne automatické odosielanie bez backendu.
const validityTypes=[['stk','STK',30,7],['ek','EK',30,7],['vignette','Diaľničná známka',14,3],['pzp','PZP',30,7]];
function validityFields(v){return validityTypes.map(([k,label])=>field('Platnosť '+label,k,v[k]||'','date')).join('')}
function editVehicleValidity(id){let v=db.vehicles.find(x=>x.id===id);if(!v)return;modal({title:'Platnosti vozidla – '+esc(v.plate),body:`<p class="muted">${esc(v.make)} · ${esc(db.customers.find(c=>c.id===v.customer)?.name||'')}</p><form class="grid two" onsubmit="saveVehicleValidity(event,'${id}')">${validityFields(v)}<div style="grid-column:1/-1"><p class="mini">Prázdne dátumy sa nesledujú. Odosielanie upozornení je zatiaľ len príprava – vyžaduje server a súhlas zákazníka.</p><button class="btn" type="submit">Uložiť platnosti</button></div></form>`})}
function saveVehicleValidity(e,id){e.preventDefault();let v=db.vehicles.find(x=>x.id===id);if(!v)return;for(let [k] of validityTypes)v[k]=e.target.elements[k].value||'';audit('Upravené platnosti vozidla '+v.plate);closeModal();render()}
function validityDays(date){if(!date)return null;let a=new Date(date+'T12:00:00'),b=new Date();b.setHours(12,0,0,0);return Math.round((a-b)/86400000)}
function validityRows(){return db.vehicles.flatMap(v=>validityTypes.filter(([k])=>v[k]).map(([k,label,first,second])=>{let days=validityDays(v[k]);return {v,key:k,label,first,second,days,date:v[k],customer:db.customers.find(c=>c.id===v.customer)||{}}})).sort((a,b)=>a.days-b.days)}
function validityBadge(d){return d<0?'<span class="pill red">Po platnosti</span>':d<=7?'<span class="pill red">Do 7 dní</span>':d<=30?'<span class="pill amber">Do 30 dní</span>':'<span class="pill green">Platné</span>'}
function expirations(){let rows=validityRows(),soon=rows.filter(r=>r.days<=30);return pageHeader('Končiace platnosti','STK, EK, diaľničné známky a PZP – kontrola a príprava e-mailových upozornení',button('Zákazníci a vozidlá',"location.hash='customers'",'outline'))+`<div class="grid four"><div class="card"><span class="mini">Po platnosti</span><h2>${rows.filter(r=>r.days<0).length}</h2></div><div class="card"><span class="mini">Do 7 dní</span><h2>${rows.filter(r=>r.days>=0&&r.days<=7).length}</h2></div><div class="card"><span class="mini">Do 30 dní</span><h2>${rows.filter(r=>r.days>=0&&r.days<=30).length}</h2></div><div class="card"><span class="mini">Evidované platnosti</span><h2>${rows.length}</h2></div></div><div class="card"><h3>Prehľad platností</h3><div class="grid two">${sel('Zobraziť','validityRange',[['all','Všetky'],['30','Do 30 dní / po platnosti'],['7','Do 7 dní / po platnosti']],'30')}${sel('Typ','validityType',[['','Všetky'],...validityTypes.map(([k,l])=>[k,l])])}</div><div class="tablewrap"><table><thead><tr><th>Vozidlo</th><th>Zákazník</th><th>Doklad</th><th>Platnosť</th><th>Stav</th><th>E-mail</th><th>Akcia</th></tr></thead><tbody>${rows.map(r=>`<tr class="validity-row" data-days="${r.days}" data-type="${r.key}"><td><strong>${esc(r.v.plate)}</strong><br><span class="mini">${esc(r.v.make)}</span></td><td>${esc(r.customer.name||'—')}</td><td>${esc(r.label)}</td><td>${esc(r.date)}</td><td>${validityBadge(r.days)}</td><td>${esc(r.customer.email||'—')}</td><td>${button('Upraviť',`editVehicleValidity('${r.v.id}')`,'small outline')} ${r.customer.email?button('Návrh e-mailu',`validityEmail('${r.v.id}','${r.key}')`,'small outline'):''}</td></tr>`).join('')||'<tr><td colspan="7">Zatiaľ nie sú vyplnené žiadne platnosti.</td></tr>'}</tbody></table></div><p class="mini">Automatické odosielanie nie je aktívne. Toto demo eviduje dátumy a pripraví e-mail v poštovom programe. Pre automatiku potrebujeme serverovú úlohu, SMTP a evidenciu súhlasu zákazníka. Predvolené pripomienky: STK/EK/PZP 30 a 7 dní; diaľničná známka 14 a 3 dni.</p></div>`}
function validityEmail(id,key){let v=db.vehicles.find(x=>x.id===id),c=db.customers.find(x=>x.id===v?.customer),t=validityTypes.find(x=>x[0]===key);if(!v||!c?.email||!t)return toast('Zákazník nemá e-mail.');let subject='AUTOSERVIS TOMI – upozornenie na platnosť '+t[1],body='Dobrý deň,\n\npripomíname, že platnosť '+t[1]+' pre vozidlo '+v.make+' ('+v.plate+') končí '+v[key]+'.\n\nS pozdravom\nAUTOSERVIS TOMI';location.href='mailto:'+encodeURIComponent(c.email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body)}
document.addEventListener('change',e=>{if(e.target.name==='validityRange'||e.target.name==='validityType'){let range=document.querySelector('[name=validityRange]')?.value||'all',type=document.querySelector('[name=validityType]')?.value||'';document.querySelectorAll('.validity-row').forEach(r=>{r.style.display=(range==='all'||Number(r.dataset.days)<=Number(range))&&(!type||r.dataset.type===type)?'':'none'})}});

window.addEventListener('hashchange',()=>{render();if(location.hash==='#jobs'&&window.tomiSelectedJob){const j=db.jobs.find(x=>x.id===window.tomiSelectedJob);if(j)document.getElementById('app').innerHTML=jobDetail(j.id)}});document.addEventListener('change',e=>{let n=e.target.name;if(n==='calMechanic'){window.calMechanic=e.target.value;render()}if(n==='histMech'){window.histMech=e.target.value;render()}if(n==='histPeriod'){window.histPeriod=e.target.value;render()}if(n==='econSegment'){window.econSegment=e.target.value;render()}if(n==='mobileMechanic'){mechanicId=e.target.value;window.mobileJob=null;render()}if(n==='mobileJob'){window.mobileJob=e.target.value;render()}if(n==='role'){role=e.target.value;sessionStorage.setItem('tomi_role',role);location.hash=role==='mechanic'?'mechanic':'dashboard';render()}});render();


// Cenová ponuka: každá položka je samostatne schvaľovaná. Prijaté položky sú v zákazkovom liste.
const VAT_RATE=0.23;
function quoteParts(j){return j.parts||[]}
function quoteLabor(j){if(!Array.isArray(j.quoteLabor)){j.quoteLabor=[];if(Number(j.labor)>0)j.quoteLabor.push({name:'Práca',qty:1,price:Number(j.labor),vat:23})}return j.quoteLabor}
function lineNet(x,kind){let amount=Number(x.qty||1)*Number(kind==='part'?x.sell:x.price||0);return kind==='part'&&x.sellVat==='s DPH'?amount/(1+VAT_RATE):amount}
function lineGross(x,kind){let net=lineNet(x,kind);return net*(1+Number(x.vat??23)/100)}
function quoteRows(j,kind){let items=kind==='part'?quoteParts(j):quoteLabor(j);return items.map((x,i)=>`<tr><td>${esc(x.name)}</td><td>${esc(x.qty||1)}</td><td>${money(kind==='part'?x.sell:x.price)}</td><td>${money(lineNet(x,kind))}</td><td>${statusPill(x.decision==='approved'?'Potvrdené':x.decision==='rejected'?'Zrušené':'Čaká')}</td><td>${button('Upraviť',`editQuoteLine('${j.id}','${kind}',${i})`,'small outline')} ${button('Potvrdiť',`decideQuoteLine('${j.id}','${kind}',${i},'approved')`,'small')} ${button('Zrušiť',`decideQuoteLine('${j.id}','${kind}',${i},'rejected')`,'small outline')}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">Zatiaľ bez položiek</td></tr>'}
function quoteView(j){quoteLabor(j);return `<div class="row between wrap"><h3>Cenová ponuka – diely</h3>${button('+ Diel',`addPart('${j.id}')`)}</div><div class="tablewrap"><table><thead><tr><th>Diel</th><th>Ks</th><th>Cena / ks</th><th>Bez DPH</th><th>Stav</th><th>Akcie</th></tr></thead><tbody>${quoteRows(j,'part')}</tbody></table></div><div class="row between wrap" style="margin-top:24px"><h3>Práca</h3>${button('+ Práca',`editQuoteLine('${j.id}','labor',-1)`)}</div><div class="tablewrap"><table><thead><tr><th>Úkon</th><th>Hodiny / ks</th><th>Cena / jednotku</th><th>Bez DPH</th><th>Stav</th><th>Akcie</th></tr></thead><tbody>${quoteRows(j,'labor')}</tbody></table></div><div class="row wrap" style="margin-top:18px">${button('PDF cenovej ponuky',`printQuote('${j.id}')`,'outline')}${button('Potvrdiť všetko',`approveAllQuote('${j.id}')`)}${button('Hromadná zmena cien dielov',`bulkPrice('${j.id}')`,'outline')}</div><p class="mini">Potvrdená položka sa okamžite prenesie do zákazkového listu. Zrušená sa neprenesie. Úprava potvrdenej položky aktualizuje jej prepojenú položku v zákazke.</p>`}
function editQuoteLine(id,kind,i){let j=db.jobs.find(x=>x.id===id),a=kind==='part'?quoteParts(j):quoteLabor(j),x=i>=0?a[i]:{name:'',qty:1,price:0,vat:23};modal({title:(i>=0?'Upraviť':'Pridať')+(kind==='part'?' diel':' prácu'),body:`<form class="grid two" onsubmit="saveQuoteLine(event,'${id}','${kind}',${i})">${field(kind==='part'?'Názov dielu':'Pracovný úkon','name',x.name,'text','required')}${field(kind==='part'?'Množstvo (ks)':'Počet hodín / jednotiek','qty',x.qty,'number','step="0.01" min="0.01" required')}${field('Cena bez DPH / jednotku (€)','price',kind==='part'?x.sell:x.price,'number','step="0.01" min="0" required')}${field('DPH (%)','vat',x.vat??23,'number','step="0.01" min="0"')}${kind==='part'?field('Nákupná cena bez DPH / ks (€)','buy',x.buy||0,'number','step="0.01" min="0"'):''}<button class="btn" type="submit">Uložiť položku</button></form>`})}
function saveQuoteLine(e,id,kind,i){e.preventDefault();let j=db.jobs.find(x=>x.id===id),a=kind==='part'?quoteParts(j):quoteLabor(j),v=formValues(e.target),old=i>=0?a[i]:{},item={...old,name:v.name,qty:Number(v.qty),vat:Number(v.vat),...(kind==='part'?{sell:Number(v.price),buy:Number(v.buy),sellVat:'bez DPH'}:{price:Number(v.price)})};if(i>=0)a[i]=item;else a.push(item);syncApproved(j);audit('Upravená položka cenovej ponuky',id);closeModal();returnQuote(id)}
function decideQuoteLine(id,kind,i,decision){let j=db.jobs.find(x=>x.id===id),a=kind==='part'?quoteParts(j):quoteLabor(j);a[i].decision=decision;syncApproved(j);audit('Položka CP: '+decision,id);returnQuote(id)}
function approveAllQuote(id){let j=db.jobs.find(x=>x.id===id);quoteParts(j).forEach(x=>x.decision='approved');quoteLabor(j).forEach(x=>x.decision='approved');j.approved=true;syncApproved(j);audit('Potvrdená celá cenová ponuka',id);returnQuote(id)}
function syncApproved(j){j.workParts=[...(j.workParts||[]).filter(x=>x.manual),...quoteParts(j).filter(x=>x.decision==='approved').map((x,i)=>({...x,source:'cp',sourceIndex:quoteParts(j).indexOf(x)}))];j.workLabor=[...(j.workLabor||[]).filter(x=>x.manual),...quoteLabor(j).filter(x=>x.decision==='approved').map(x=>({...x,source:'cp',sourceIndex:quoteLabor(j).indexOf(x)}))];}
function workOrderView(j){let parts=j.workParts||[],labor=j.workLabor||[],pn=parts.reduce((s,x)=>s+lineNet(x,'part'),0),ln=labor.reduce((s,x)=>s+lineNet(x,'labor'),0),pg=parts.reduce((s,x)=>s+lineGross(x,'part'),0),lg=labor.reduce((s,x)=>s+lineGross(x,'labor'),0);let rows=(items,kind)=>items.map((x,i)=>`<tr><td>${esc(x.name)}</td><td>${esc(x.qty)}</td><td>${money(lineNet(x,kind))}</td><td>${button('Upraviť',`editWorkLine('${j.id}','${kind}',${i})`,'small outline')} ${button('Odobrať',`removeWorkLine('${j.id}','${kind}',${i})`,'small outline')}</td></tr>`).join('')||'<tr><td colspan="4">Bez položiek</td></tr>';return `<h3>Zákazkový list – ${esc(j.id)}</h3><p class="mini">Schválené položky CP sa prenášajú automaticky. V zákazke možno položky samostatne doplniť a upraviť.</p><div class="row between wrap"><h3>Diely</h3>${button('+ Pridať diel',`editWorkLine('${j.id}','part',-1)`)}</div><div class="tablewrap"><table><thead><tr><th>Diel</th><th>Ks</th><th>Bez DPH</th><th>Akcie</th></tr></thead><tbody>${rows(parts,'part')}</tbody></table></div><div class="row between wrap" style="margin-top:24px"><h3>Práca</h3>${button('+ Pridať prácu',`editWorkLine('${j.id}','labor',-1)`)}</div><div class="tablewrap"><table><thead><tr><th>Práca</th><th>Hodiny / ks</th><th>Bez DPH</th><th>Akcie</th></tr></thead><tbody>${rows(labor,'labor')}</tbody></table></div><div class="grid two" style="margin-top:24px"><div class="card"><h3>Bez DPH</h3><p>Práca: <strong>${money(ln)}</strong></p><p>Diely: <strong>${money(pn)}</strong></p><h3>Spolu: ${money(ln+pn)}</h3></div><div class="card"><h3>S DPH</h3><p>Práca: <strong>${money(lg)}</strong></p><p>Diely: <strong>${money(pg)}</strong></p><h3>Spolu: ${money(lg+pg)}</h3></div></div><div class="grid two" style="margin-top:24px"><div><h3>Fotografie a dokumenty</h3><div class="row wrap">${button('+ Fotografie',`addJobPhotos('${j.id}')`,'outline')}${button('+ Dokumenty',`addJobDocuments('${j.id}')`,'outline')}</div><div class="row wrap">${(j.photos||[]).map(p=>`<div class="card"><img src="${esc(p.data)}" alt="" style="max-width:110px;max-height:90px"><p class="mini">${esc(p.name)}</p></div>`).join('')}${(j.documents||[]).map(d=>`<p class="mini">📄 ${esc(d.name)}</p>`).join('')}</div></div><div><h3>Poznámky a odporúčania pre zákazníka</h3><textarea id="workOrderNotes" rows="8" style="width:100%" placeholder="Odporúčame výmenu oleja po 15 000 km...">${esc(j.workOrderNotes||'')}</textarea>${button('Uložiť poznámky',`saveWorkOrderNotes('${j.id}')`,'outline')}</div></div><p class="notice warn">Údaje a prílohy sú zatiaľ iba v lokálnom demo úložisku. DPH je predvolene 23 %; pred ostrou prevádzkou overiť daňový režim.</p>`}
function saveWorkOrderNotes(id){let j=db.jobs.find(x=>x.id===id);j.workOrderNotes=document.getElementById('workOrderNotes').value;audit('Uložené odporúčania zákazky',id);openJob(id,'workorder')}
function editWorkLine(id,kind,i){let j=db.jobs.find(x=>x.id===id),a=kind==='part'?(j.workParts||[]):(j.workLabor||[]),x=i>=0?a[i]:{name:'',qty:1,vat:23};modal({title:(i<0?'Pridať':'Upraviť')+(kind==='part'?' diel':' prácu'),body:`<form class="grid two" onsubmit="saveWorkLine(event,'${id}','${kind}',${i})">${field('Názov','name',x.name,'text','required')}${field('Množstvo / hodiny','qty',x.qty,'number','step="0.01" min="0.01" required')}${field('Cena za jednotku bez DPH','price',kind==='part'?x.sell:x.price,'number','step="0.01" min="0" required')}${field('DPH (%)','vat',x.vat??23,'number','step="0.01" min="0"')}${kind==='part'?field('Nákupná cena / ks','buy',x.buy||0,'number','step="0.01" min="0"'):''}<button class="btn">Uložiť</button></form>`})}
function saveWorkLine(e,id,kind,i){e.preventDefault();let j=db.jobs.find(x=>x.id===id),a=kind==='part'?(j.workParts=j.workParts||[]):(j.workLabor=j.workLabor||[]),v=formValues(e.target),item={name:v.name,qty:Number(v.qty),vat:Number(v.vat),manual:true,...(kind==='part'?{sell:Number(v.price),buy:Number(v.buy),sellVat:'bez DPH'}:{price:Number(v.price)})};if(i>=0)a[i]=item;else a.push(item);audit('Upravený zákazkový list',id);closeModal();openJob(id,'workorder')}
function removeWorkLine(id,kind,i){if(!confirm('Odobrať položku zo zákazky?'))return;let j=db.jobs.find(x=>x.id===id),a=kind==='part'?j.workParts:j.workLabor;a.splice(i,1);audit('Odstránená položka zákazky',id);openJob(id,'workorder')}
function addJobDocuments(id){let input=document.createElement('input');input.type='file';input.accept='image/*,application/pdf';input.multiple=true;input.onchange=async()=>{let j=db.jobs.find(x=>x.id===id);j.documents=j.documents||[];for(let f of input.files){if(f.size>500000){toast('Maximálna veľkosť dokumentu v deme je 500 kB');continue}let data=await new Promise(resolve=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(f)});j.documents.push({name:f.name,data})}try{audit('Pridané dokumenty',id)}catch(e){toast('Úložisko je plné');return}openJob(id,'workorder')};input.click()}
function printSheetHtml(title,html){let w=window.open('','_blank');if(!w)return toast('Povoľte vyskakovacie okná');w.document.write(`<!doctype html><html lang="sk"><head><meta charset="utf-8"><title>${title}</title><style>body{font:13px Arial,sans-serif;color:#15243b;margin:34px}header{border-bottom:4px solid #1b66b5;padding-bottom:18px;margin-bottom:24px}h1{font-size:24px;margin:4px 0}h2{font-size:16px;margin-top:25px}small{color:#66758a}table{width:100%;border-collapse:collapse;margin-top:12px}th{background:#eef3f9;text-align:left}td,th{border-bottom:1px solid #d8e1eb;padding:9px} .cols{display:grid;grid-template-columns:1fr 1fr;gap:24px}.note{white-space:pre-wrap;background:#f6f8fb;padding:16px;min-height:70px}.writing{height:160px;border-bottom:1px solid #a9b7c9;background:repeating-linear-gradient(to bottom,white 0px,white 31px,#d6dee9 32px)}.tot{font-weight:bold;font-size:17px;text-align:right;margin-top:20px}@media print{button{display:none}}</style></head><body><header><small>AUTOSERVIS TOMI · SERVISNÁ DOKUMENTÁCIA</small><h1>${title}</h1></header>${html}<script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
function printWorkSheet(id,type){let j=db.jobs.find(x=>x.id===id),c=customerOf(db,j),v=vehicleOf(db,j),base=`<p><b>Zákazka:</b> ${esc(id)} · <b>Dátum:</b> ${esc(j.date||'')}</p><p><b>Vozidlo:</b> ${esc(v.make)} · <b>ŠPZ:</b> ${esc(v.plate)} · <b>VIN:</b> ${esc(v.vin||'—')} · <b>Km:</b> ${esc(j.km??v.km??'—')}</p>`;if(type==='technician')return printSheetHtml('ZÁKAZKOVÝ LIST – TECHNIK',base+`<h2>Požiadavky a poznámky</h2><div class="note">${esc(j.description||'—')}</div><h2>Zistenia / vykonané úkony</h2><div class="writing"></div><div class="writing"></div><p>Mechanik: ______________________ &nbsp; Dátum: _______________</p>`);let p=j.workParts||[],l=j.workLabor||[],rows=(a,k)=>a.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.qty)}</td><td>${money(lineNet(x,k))}</td><td>${money(lineGross(x,k))}</td></tr>`).join('');let pn=p.reduce((a,x)=>a+lineNet(x,'part'),0),ln=l.reduce((a,x)=>a+lineNet(x,'labor'),0),pg=p.reduce((a,x)=>a+lineGross(x,'part'),0),lg=l.reduce((a,x)=>a+lineGross(x,'labor'),0);return printSheetHtml('ZÁKAZKOVÝ LIST – ZÁKAZNÍK',`<div class="cols"><div><h2>Dodávateľ</h2><b>AUTOSERVIS TOMI</b><p>Firemné a fakturačné údaje doplníme v nastaveniach pred ostrou prevádzkou.</p></div><div><h2>Odberateľ</h2><b>${esc(c.name)}</b><p>${esc(c.address||'')}</p><p>${esc(c.ico?'IČO: '+c.ico:'')} ${esc(c.icdph?'IČ DPH: '+c.icdph:'')}</p></div></div>${base}<h2>Náhradné diely</h2><table><tr><th>Diel</th><th>Množstvo</th><th>Bez DPH</th><th>S DPH</th></tr>${rows(p,'part')}</table><h2>Práca</h2><table><tr><th>Úkon</th><th>Hodiny / ks</th><th>Bez DPH</th><th>S DPH</th></tr>${rows(l,'labor')}</table><table><tr><th></th><th>Bez DPH</th><th>S DPH</th></tr><tr><td>Diely</td><td>${money(pn)}</td><td>${money(pg)}</td></tr><tr><td>Práca</td><td>${money(ln)}</td><td>${money(lg)}</td></tr><tr><th>SPOLU</th><th>${money(pn+ln)}</th><th>${money(pg+lg)}</th></tr></table><h2>Poznámky a odporúčania</h2><div class="note">${esc(j.workOrderNotes||'—')}</div><p style="margin-top:40px">Prevzal: ________________________ &nbsp; Dátum: ______________</p>`)}
function printQuote(id){let j=db.jobs.find(x=>x.id===id),c=customerOf(db,j),v=vehicleOf(db,j);let rows=(a,k)=>a.filter(x=>x.decision!=='rejected').map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.qty)}</td><td>${money(lineNet(x,k))}</td><td>${money(lineGross(x,k))}</td></tr>`).join('');printSheetHtml('CENOVÁ PONUKA',`<p><b>Zákazka:</b> ${esc(id)} · <b>Zákazník:</b> ${esc(c.name)} · <b>Vozidlo:</b> ${esc(v.make)} · ${esc(v.plate)}</p><h2>Diely</h2><table><tr><th>Položka</th><th>Ks</th><th>Bez DPH</th><th>S DPH</th></tr>${rows(quoteParts(j),'part')}</table><h2>Práca</h2><table><tr><th>Úkon</th><th>Hodiny</th><th>Bez DPH</th><th>S DPH</th></tr>${rows(quoteLabor(j),'labor')}</table>`)}
function printHistory(id){let j=db.jobs.find(x=>x.id===id);printSheetHtml('HISTÓRIA ZÁKAZKY',`<p>${esc(id)}</p>${db.activity.filter(a=>a.job===id).map(a=>`<p>${esc(a.time)} – ${esc(a.text)}</p>`).join('')||'<p>Bez záznamov</p>'}`)}

function openQuoteOnly(id){let j=db.jobs.find(x=>x.id===id);if(!j)return;location.hash='quotes';render();document.getElementById('app').innerHTML=pageHeader('Cenová ponuka · '+esc(id),esc(jobLabel(j)),button('← Zoznam CP',"location.hash='quotes';render()",'outline'))+`<div class="card">${quoteView(j)}</div>`}
function returnQuote(id){if(location.hash==='#quotes')openQuoteOnly(id);else openJob(id,'quote')}
function closeJobView(j){return `<h3>Ukončenie zákazky</h3><p>Ukončená zákazka prestane byť aktívna. Vozidlo môže zostať v areáli až do odovzdania zákazníkovi.</p>${button('Ukončiť zákazku',`closeJobModal('${j.id}')`)}${j.status==='Ukončená'&&!j.handedOver?button('Potvrdiť odovzdanie vozidla',`handoverJob('${j.id}')`,'outline'):''}<p>Vyúčtovanie: ${esc(j.invoiceNumber?'Faktúra '+j.invoiceNumber:j.billingType||'—')}</p>`}
function closeJobModal(id){let j=db.jobs.find(x=>x.id===id);modal({title:'Ukončiť zákazku · '+esc(id),body:`<form class="stack" onsubmit="finishJob(event,'${id}')">${sel('Vyúčtovanie','billingType',[['Faktúra','Faktúra'],['Hotovosť','Hotovosť / FO']],j.billingType||'Faktúra')}${field('Číslo faktúry (ak je vystavená)','invoiceNumber',j.invoiceNumber||'')}<label><input type="checkbox" name="handedOver" ${j.handedOver?'checked':''}> Vozidlo bolo odovzdané zákazníkovi</label><button class="btn" type="submit">Potvrdiť ukončenie zákazky</button></form>`})}
function finishJob(e,id){e.preventDefault();let j=db.jobs.find(x=>x.id===id),v=formValues(e.target);if(v.billingType==='Faktúra'&&!v.invoiceNumber.trim())return toast('Vyplňte číslo faktúry.');j.billingType=v.billingType;j.invoiceNumber=v.billingType==='Faktúra'?v.invoiceNumber.trim():'';j.status='Ukončená';j.finishedAt=j.finishedAt||new Date().toISOString();j.handedOver=!!v.handedOver;if(j.handedOver)changeVehicleStage(j,'Odovzdané');else changeVehicleStage(j,'Na odovzdanie');j.status='Ukončená';j.finishedAt=j.finishedAt||new Date().toISOString();audit('Ukončená zákazka: '+j.billingType,id);closeModal();openJob(id,'close')}
function handoverJob(id){let j=db.jobs.find(x=>x.id===id);j.handedOver=true;changeVehicleStage(j,'Odovzdané');j.status='Ukončená';j.finishedAt=j.finishedAt||new Date().toISOString();audit('Vozidlo odovzdané zákazníkovi',id);openJob(id,'close')}
function addJobPhotos(id){let inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.multiple=true;inp.onchange=async()=>{let j=db.jobs.find(x=>x.id===id);j.photos=j.photos||[];for(const file of Array.from(inp.files||[])){if(file.size>700000){toast('Fotografia '+file.name+' je príliš veľká (max 700 kB v demo verzii).');continue}let data=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});j.photos.push({name:file.name,data})}try{audit('Pridané fotografie k zákazke',id)}catch(e){toast('Úložisko prehliadača je plné. Fotografie neboli bezpečne uložené.');return}openJob(id,'workorder')};inp.click()}

function saveJobDescription(id){let j=db.jobs.find(x=>x.id===id);j.description=document.getElementById("jobDescription").value;audit("Upravené poznámky",id);openJob(id,"overview")}

function newQuote(){modal({title:"Nová cenová ponuka",body:`<p>Vyberte zákazku, ku ktorej chcete vytvoriť cenovú ponuku.</p><div class="stack">${sel("Zákazka","newQuoteJob",db.jobs.map(j=>[j.id,j.id+" · "+customerOf(db,j).name+" · "+vehicleOf(db,j).plate]))}${button("Otvoriť editor CP","let id=document.querySelector('[name=newQuoteJob]').value;closeModal();openQuoteOnly(id)")}${button("Nová zákazka","closeModal();newJob()","outline")}</div>`})}
